import { Link } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

export default function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const navLinks = [
    { href: '#about', label: 'About' },
    { href: '#contact', label: 'Contact' },
  ];

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled
          ? 'bg-background/95 backdrop-blur-md border-b border-border'
          : 'bg-transparent border-b border-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className="flex h-16 md:h-20 items-center justify-between">
          {/* Logo / Initials */}
          <Link
            to="/"
            className="text-sm font-medium tracking-[0.2em] uppercase text-foreground hover:text-primary transition-colors duration-200"
          >
            AM
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navLinks.map((link) => (
              <a
                key={link.href}
                href={link.href}
                className="relative text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors duration-200 group"
              >
                {link.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-200 group-hover:w-full" />
              </a>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setMobileOpen(!mobileOpen)}
            className="md:hidden text-muted-foreground hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {mobileOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <div className="md:hidden bg-background/98 backdrop-blur-md border-t border-border px-6 py-6">
          <nav className="flex flex-col gap-5">
            {navLinks.map((link) => (
              <a
                key={link.href}
                href={link.href}
                onClick={() => setMobileOpen(false)}
                className="text-sm tracking-widest uppercase text-muted-foreground hover:text-primary transition-colors duration-200"
              >
                {link.label}
              </a>
            ))}
          </nav>
        </div>
      )}
    </header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  return (
    <footer className="bg-background border-t border-border">
      <div className="max-w-7xl mx-auto px-6 md:px-12 py-8">
        <p className="text-xs tracking-widest uppercase text-muted-foreground">
          © {currentYear} Alex Morgan. All rights reserved.
        </p>
      </div>
    </footer>
  );
}

import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, ArrowDown, Mail } from 'lucide-react';

// ─── Animation variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.55, ease: 'easeOut' as const, delay },
  }),
};

const fadeIn = {
  hidden: { opacity: 0, y: 16 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.4, ease: 'easeOut' as const },
  },
};

// ─── Decorative SVG ───────────────────────────────────────────────────────────

function GeometricAccent() {
  return (
    <svg
      viewBox="0 0 320 320"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className="w-full max-w-xs md:max-w-sm opacity-60"
      aria-hidden="true"
    >
      {/* Outer square rotated */}
      <rect
        x="40"
        y="40"
        width="240"
        height="240"
        stroke="hsl(var(--primary))"
        strokeWidth="1"
        strokeDasharray="4 8"
        transform="rotate(15 160 160)"
      />
      {/* Inner square */}
      <rect
        x="90"
        y="90"
        width="140"
        height="140"
        stroke="hsl(var(--primary))"
        strokeWidth="0.75"
        transform="rotate(-8 160 160)"
      />
      {/* Center cross */}
      <line x1="160" y1="60" x2="160" y2="260" stroke="hsl(var(--primary))" strokeWidth="0.5" />
      <line x1="60" y1="160" x2="260" y2="160" stroke="hsl(var(--primary))" strokeWidth="0.5" />
      {/* Corner dots */}
      <circle cx="160" cy="160" r="4" fill="hsl(var(--primary))" />
      <circle cx="100" cy="100" r="2" fill="hsl(var(--primary))" opacity="0.6" />
      <circle cx="220" cy="100" r="2" fill="hsl(var(--primary))" opacity="0.6" />
      <circle cx="100" cy="220" r="2" fill="hsl(var(--primary))" opacity="0.6" />
      <circle cx="220" cy="220" r="2" fill="hsl(var(--primary))" opacity="0.6" />
      {/* Outer ring arc */}
      <circle
        cx="160"
        cy="160"
        r="120"
        stroke="hsl(var(--primary))"
        strokeWidth="0.5"
        strokeDasharray="2 12"
        opacity="0.4"
      />
    </svg>
  );
}

// ─── Social icon link ─────────────────────────────────────────────────────────

interface SocialLinkProps {
  href: string;
  label: string;
  icon: React.ReactNode;
}

function SocialLink({ href, label, icon }: SocialLinkProps) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={label}
      className="text-muted-foreground hover:text-primary transition-colors duration-200"
    >
      {icon}
    </a>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function HomePage() {
  return (
    <main className="bg-background text-foreground">
      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <section className="relative min-h-screen flex flex-col justify-center overflow-hidden px-6 md:px-12 pt-24 pb-16">
        {/* Subtle background grid */}
        <div
          className="pointer-events-none absolute inset-0 opacity-[0.03]"
          style={{
            backgroundImage:
              'linear-gradient(hsl(var(--primary)) 1px, transparent 1px), linear-gradient(90deg, hsl(var(--primary)) 1px, transparent 1px)',
            backgroundSize: '80px 80px',
          }}
          aria-hidden="true"
        />

        <div className="max-w-7xl mx-auto w-full">
          {/* Overline */}
          <motion.p
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-8 md:mb-10"
          >
            Portfolio
          </motion.p>

          {/* Oversized name — architectural treatment */}
          <div className="overflow-hidden">
            <motion.h1
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.1}
              className="font-heading text-[clamp(3.5rem,12vw,10rem)] leading-[0.9] tracking-tight text-foreground"
            >
              Alex
            </motion.h1>
          </div>
          <div className="overflow-hidden">
            <motion.h1
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.22}
              className="font-heading text-[clamp(3.5rem,12vw,10rem)] leading-[0.9] tracking-tight text-foreground"
            >
              Morgan
            </motion.h1>
          </div>

          {/* Tagline — offset right */}
          <motion.div
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.38}
            className="mt-8 md:mt-10 md:ml-auto md:max-w-md"
          >
            {/* Accent rule */}
            <div className="w-8 h-px bg-primary mb-4" />
            <p className="text-base md:text-lg text-muted-foreground leading-relaxed">
              Designer &amp; Developer crafting thoughtful digital experiences.
            </p>
          </motion.div>
        </div>

        {/* Scroll indicator */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.1, duration: 0.6 }}
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-muted-foreground"
          aria-hidden="true"
        >
          <span className="text-[10px] tracking-[0.25em] uppercase">Scroll</span>
          <motion.div
            animate={{ y: [0, 6, 0] }}
            transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' }}
          >
            <ArrowDown size={14} />
          </motion.div>
        </motion.div>
      </section>

      {/* ── ABOUT ────────────────────────────────────────────────────────── */}
      <section id="about" className="py-28 md:py-36 px-6 md:px-12">
        <div className="max-w-7xl mx-auto">
          {/* Section label */}
          <motion.p
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-12"
          >
            About
          </motion.p>

          <div className="grid md:grid-cols-2 gap-16 md:gap-24 items-center">
            {/* Left — bio */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
            >
              <h2 className="font-heading text-4xl md:text-5xl text-foreground mb-8 leading-tight">
                Craft over<br />convention.
              </h2>
              {/* Accent rule */}
              <div className="w-8 h-px bg-primary mb-8" />
              <div className="space-y-5 text-muted-foreground leading-[1.85] text-base md:text-[1.0625rem]">
                <p>
                  With a background spanning interaction design and front-end engineering, I work at
                  the intersection of aesthetics and function — building interfaces that feel as
                  considered as they look.
                </p>
                <p>
                  I'm drawn to projects where clarity matters: products that need to communicate
                  complex ideas simply, or experiences that earn trust through restraint rather than
                  noise.
                </p>
                <p>
                  Collaboration is central to how I work. The best outcomes come from close
                  partnership with product, engineering, and the people who actually use what we
                  build.
                </p>
              </div>
            </motion.div>

            {/* Right — geometric decorative element */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="flex items-center justify-center"
            >
              <GeometricAccent />
            </motion.div>
          </div>
        </div>
      </section>

      {/* Divider */}
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className="h-px bg-border" />
      </div>

      {/* ── CONTACT ──────────────────────────────────────────────────────── */}
      <section id="contact" className="py-28 md:py-36 px-6 md:px-12">
        <div className="max-w-7xl mx-auto">
          {/* Section label */}
          <motion.p
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-12"
          >
            Contact
          </motion.p>

          <div className="grid md:grid-cols-2 gap-16 md:gap-24 items-start">
            {/* Left — heading */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
            >
              <h2 className="font-heading text-4xl md:text-5xl text-foreground leading-tight">
                Let's make<br />something<br />together.
              </h2>
            </motion.div>

            {/* Right — email + socials */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="flex flex-col justify-center gap-10"
            >
              {/* Email */}
              <div>
                <p className="text-xs tracking-[0.2em] uppercase text-muted-foreground mb-3">
                  Email
                </p>
                <a
                  href="mailto:alex@example.com"
                  className="group inline-flex items-center gap-3 text-foreground hover:text-primary transition-colors duration-200"
                >
                  <Mail size={16} className="shrink-0 text-primary" />
                  <span className="text-lg relative">
                    alex@example.com
                    <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
                  </span>
                </a>
              </div>

              {/* Social links */}
              <div>
                <p className="text-xs tracking-[0.2em] uppercase text-muted-foreground mb-4">
                  Elsewhere
                </p>
                <div className="flex items-center gap-6">
                  <SocialLink
                    href="https://github.com"
                    label="GitHub"
                    icon={<Github size={20} />}
                  />
                  <SocialLink
                    href="https://linkedin.com"
                    label="LinkedIn"
                    icon={<Linkedin size={20} />}
                  />
                  <SocialLink
                    href="https://twitter.com"
                    label="Twitter / X"
                    icon={<Twitter size={20} />}
                  />
                </div>
              </div>
            </motion.div>
          </div>
        </div>
      </section>
    </main>
  );
}

